const slides=[{src:'assets/hero-studio.png',label:'01 / THE STUDIO',alt:'Orange-lit DevMania studio with laptop and Dubai skyline'},{src:'assets/hero-world.png',label:'02 / IDEAS WITHOUT BORDERS',alt:'DevMania creative workspace with a glowing orange globe'},{src:'assets/hero-build.png',label:'03 / ALWAYS BUILDING',alt:'DevMania app and website artwork with an illustrated loading bar'}];
const stage=document.querySelector('.flip-stage'),hero=document.querySelector('#hero-image'),label=document.querySelector('#slide-label'),dots=[...document.querySelectorAll('[data-slide]')],pause=document.querySelector('#pause'),carousel=document.querySelector('.carousel');
let current=0,busy=false,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer;
slides.forEach(s=>{const image=new Image();image.src=s.src});
function updatePause(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Play carousel':'Pause carousel')}
function schedule(){clearInterval(timer);if(!paused&&!document.hidden)timer=setInterval(()=>show(current+1),6000)}
function apply(index){current=(index+slides.length)%slides.length;hero.src=slides[current].src;hero.alt=slides[current].alt;label.textContent=slides[current].label;dots.forEach((d,i)=>{d.classList.toggle('active',i===current);if(i===current)d.setAttribute('aria-current','true');else d.removeAttribute('aria-current')})}
function show(index){if(busy||((index+3)%3===current))return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){apply(index);return}busy=true;stage.classList.add('flip-out');setTimeout(()=>{apply(index);stage.classList.remove('flip-out');stage.classList.add('flip-in');setTimeout(()=>{stage.classList.remove('flip-in');busy=false},480)},380)}
document.querySelector('#next').onclick=()=>{show(current+1);schedule()};document.querySelector('#prev').onclick=()=>{show(current-1);schedule()};dots.forEach(d=>d.onclick=()=>{show(Number(d.dataset.slide));schedule()});pause.onclick=()=>{paused=!paused;updatePause();schedule()};carousel.addEventListener('mouseenter',()=>clearInterval(timer));carousel.addEventListener('mouseleave',schedule);carousel.addEventListener('focusin',()=>clearInterval(timer));carousel.addEventListener('focusout',e=>{if(!carousel.contains(e.relatedTarget))schedule()});document.addEventListener('visibilitychange',schedule);updatePause();schedule();
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const message=`Hello DevMania! I would like to discuss a project.\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nProject type: ${f.get('type')}\n\nProject outline:\n${f.get('idea')}`;window.open('https://wa.me/971566407476?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');document.querySelector('#form-status').textContent='Your enquiry is ready in WhatsApp. Tap Send there to send it to DevMania.'});
